async (page) => {
  // 1. 공격 작전 그룹 안의 "코치에게" 버튼 클릭
  await page.locator('[role="dialog"] button:has-text("코치에게")').first().click();
  // 2. 모달 내의 "저장" 버튼 클릭
  await page.locator('[role="dialog"] button:has-text("저장")').click();
  // 3. 잠시 대기 후 "경기 시작" 버튼 클릭
  await page.locator('main button:has-text("경기 시작")').click();
}
